 46→
 47→function formatStatus(status: string): string {
 48→  return status.charAt(0).toUpperCase() + status.slice(1);
 49→}
 50→
 51→function formatQuizType(type: string): string {
 52→  return type
 53→    .split("-")
 54→    .map((word) => word.charAt(0).toUpperCase() + word.slice(1))
 55→    .join(" ");
 56→}
