124→// --- Loader ---
125→
126→export const loader = async ({ request }: LoaderFunctionArgs) => {
127→  const { session } = await authenticate.admin(request);
128→  try {
129→    const quizzes = await getQuizzes(session.shop);
130→    return { quizzes };
131→  } catch {
132→    return { quizzes: [] };
133→  }
134→};
135→
136→// --- Action ---
137→
138→export const action = async ({ request }: ActionFunctionArgs) => {
139→  const { session } = await authenticate.admin(request);
140→  const formData = await request.formData();
141→  const intent = formData.get("intent") as string;
142→  const id = formData.get("id") as string;
143→
144→  try {
145→    if (intent === "archive") {
146→      const quiz = await db.quiz.findFirst({
147→        where: { id, shop: session.shop },
148→      });
149→      if (!quiz) {
150→        return data({ error: "Quiz not found or access denied" }, { status: 404 });
151→      }
152→      await db.quiz.update({
153→        where: { id },
154→        data: { status: "archived" },
155→      });
156→      return { success: true, message: "Quiz archived" };
157→    }
158→
159→    if (intent === "delete") {
160→      await deleteQuiz(id, session.shop);
161→      return { success: true, message: "Quiz deleted" };
162→    }
163→
164→    return data({ error: "Unknown intent" }, { status: 400 });
165→  } catch (error) {
166→    return data({ error: "Action failed" }, { status: 500 });
167→  }
168→};
