381→  const [showAIOverlay, setShowAIOverlay] = useState(false);
382→  const [selectedTemplate, setSelectedTemplate] = useState<string | null>(null);
383→
384→  const showEmptyState = quizzes.length === 0;
385→
386→  const handleOpenModal = useCallback(() => {
387→    setModalOpen(true);
388→  }, []);
389→
390→  const handleCloseModal = useCallback(() => {
391→    setModalOpen(false);
392→  }, []);
393→
394→  const handleSelectTemplate = useCallback(
395→    (templateId: string) => {
