398→
399→      if (templateId === "blank") {
400→        navigate("/app/quizzes/new");
401→      } else {
402→        setShowAIOverlay(true);
403→      }
404→    },
405→    [navigate],
406→  );
407→
408→  const handleAIComplete = useCallback(() => {
409→    setShowAIOverlay(false);
410→    showToast("Quiz created successfully!");
411→    navigate(`/app/quizzes/new?template=${selectedTemplate}`);
412→  }, [navigate, selectedTemplate]);
413→
414→  const handleEditQuiz = useCallback(
415→    (id: string) => {
416→      navigate(`/app/quizzes/${id}`);
417→    },
418→    [navigate],
419→  );
420→
421→  const handlePreviewQuiz = useCallback(
422→    (id: string) => {
423→      navigate(`/app/quizzes/${id}/preview`);
424→    },
425→    [navigate],
426→  );
427→
428→  const handleArchiveQuiz = useCallback(
429→    (id: string) => {
430→      const formData = new FormData();
431→      formData.append("intent", "archive");
432→      formData.append("id", id);
433→      submit(formData, { method: "POST" });
434→      showToast("Quiz archived");
435→    },
436→    [submit],
437→  );
438→
439→  const resourceName = { singular: "quiz", plural: "quizzes" };
440→  const { selectedResources, allResourcesSelected, handleSelectionChange } =
441→    useIndexResourceState(quizzes);
442→
443→  const rowMarkup = quizzes.map(
