520→            >
521→              Preview
522→            </Button>
523→            <Button
524→              size="slim"
525→              variant="plain"
526→              tone="critical"
527→              onClick={() => handleArchiveQuiz(quiz.id)}
528→            >
529→              Archive
530→            </Button>
531→          </ButtonGroup>
532→        </IndexTable.Cell>
533→      </IndexTable.Row>
534→    ),
535→  );
536→
537→  return (
538→    <>
539→      {showAIOverlay && <AIGenerationOverlay onComplete={handleAIComplete} />}
540→
541→      <Page
542→        title="My Quizzes"
543→        primaryAction={{
544→          content: "+ Create quiz",
545→          onAction: handleOpenModal,
546→        }}
547→      >
548→        <BlockStack gap="600">
549→          {showEmptyState ? (
550→            <Card>
551→              <EmptyState
552→                heading="Create your first quiz"
553→                action={{
554→                  content: "Create quiz",
555→                  onAction: handleOpenModal,
556→                }}
557→                image="https://cdn.shopify.com/s/files/1/0262/4071/2726/files/emptystate-files.png"
558→              >
559→                <p>
560→                  Build product recommendation quizzes that help your customers
561→                  find the perfect product and boost your sales.
562→                </p>
563→              </EmptyState>
564→            </Card>
565→          ) : (
566→            <Layout>
567→              <Layout.Section>
568→                <Card padding="0">
569→                  <BlockStack>
570→                    <Box padding="400">
571→                      <InlineStack align="space-between" blockAlign="center">
572→                        <Text as="h2" variant="headingMd">
573→                          All Quizzes
574→                        </Text>
575→                        <Text as="p" variant="bodySm" tone="subdued">
576→                          {quizzes.length} {quizzes.length === 1 ? "quiz" : "quizzes"}
577→                        </Text>
578→                      </InlineStack>
579→                    </Box>
580→                    <IndexTable
581→                      resourceName={resourceName}
582→                      itemCount={quizzes.length}
583→                      selectedItemsCount={
584→                        allResourcesSelected
585→                          ? "All"
586→                          : selectedResources.length
587→                      }
588→                      onSelectionChange={handleSelectionChange}
589→                      headings={[
590→                        { title: "Quiz" },
591→                        { title: "Status" },
592→                        { title: "Questions", alignment: "end" },
593→                        { title: "Completions", alignment: "end" },
594→                        { title: "Conv. Rate", alignment: "end" },
595→                        { title: "Revenue", alignment: "end" },
596→                        { title: "Updated" },
597→                        { title: "Actions" },
598→                      ]}
599→                    >
600→                      {rowMarkup}
601→                    </IndexTable>
602→                  </BlockStack>
603→                </Card>
604→              </Layout.Section>
605→            </Layout>
606→          )}
607→        </BlockStack>
608→      </Page>
609→
610→      <Modal open={modalOpen} onClose={handleCloseModal} title="Choose a template">
611→        <Box padding="400">
612→          <BlockStack gap="400">
613→            <Text as="h2" variant="headingLg" fontWeight="bold">
614→              Choose a template
615→            </Text>
616→            <Text as="p" variant="bodyMd" tone="subdued">
617→              Pick a pre-built quiz template or start from scratch
618→            </Text>
619→            <Divider />
620→            <div
621→              style={{
622→                display: "grid",
623→                gridTemplateColumns: "repeat(3, 1fr)",
624→                gap: "16px",
625→              }}
626→            >
627→              {templates.map((template) => (
628→                <TemplateCard
629→                  key={template.id}
630→                  template={template}
631→                  onSelect={handleSelectTemplate}
632→                />
633→              ))}
634→            </div>
635→          </BlockStack>
636→        </Box>
637→      </Modal>
638→    </>
639→  );
640→}
