  3→function slugify(text: string): string {
  4→  return (
  5→    text
  6→      .toLowerCase()
  7→      .replace(/[^a-z0-9\s-]/g, "")
  8→      .replace(/\s+/g, "-")
  9→      .replace(/-+/g, "-")
 10→      .replace(/^-|-$/g, "") || "quiz"
 11→  );
