export function getTemplatesMeta(): TemplateMeta[] {
  return TEMPLATE_DEFINITIONS.map((t) => t.meta);
}

export async function createQuizFromTemplate(
  shop: string,
  templateId: string,
): Promise<string> {
  const definition = TEMPLATE_DEFINITIONS.find((t) => t.meta.id === templateId);
  if (!definition) {
    throw new Error(`Template "${templateId}" not found`);
  }

  // Generate a unique slug from the quiz title
  const baseSlug = definition.title
    .toLowerCase()
    .replace(/[^a-z0-9\s-]/g, "")
    .replace(/\s+/g, "-")
    .replace(/-+/g, "-")
    .replace(/^-|-$/g, "") || "quiz";

  let slug = baseSlug;
  let counter = 0;
  while (await db.quiz.findFirst({ where: { shop, slug } })) {
    counter++;
    slug = `${baseSlug}-${counter}`;
  }

  const quiz = await db.quiz.create({
    data: {
      shop,
      slug,
      title: definition.title,
      type: definition.type,
      description: definition.description,
      questions: {
        create: definition.questions.map((q) => ({
          type: q.type,
          title: q.title,
          description: q.description ?? null,
          position: q.position,
          required: true,
          settings: "{}",
          logic: "{}",
          answers: q.answers.length > 0
            ? {
                create: q.answers.map((a) => ({
                  text: a.text,
                  position: a.position,
                  score: a.score,
                  productTags: JSON.stringify(a.productTags),
                  metadata: "{}",
                })),
              }
            : undefined,
        })),
      },
      resultPages: {
        create: [
          {
            title: "Your Recommendations",
            description: "Based on your answers, here are the products we recommend for you.",
            type: "default",
            position: 0,
            productLimit: 4,
            layout: "grid",
            matchTags: "[]",
            styling: "{}",
          },
        ],
      },
    },
  });

  return quiz.id;
}

export async function createBlankQuiz(shop: string): Promise<string> {
  // Generate a unique slug
  const baseSlug = "my-quiz";
  let slug = baseSlug;
  let counter = 0;
  while (await db.quiz.findFirst({ where: { shop, slug } })) {
    counter++;
    slug = `${baseSlug}-${counter}`;
  }

  const quiz = await db.quiz.create({
    data: {
      shop,
      slug,
      title: "My Quiz",
      type: "product-recommendation",
      description: null,
      settings: "{}",
      styling: "{}",
      resultPages: {
        create: [
          {
            title: "Your Results",
            type: "default",
            position: 0,
            productLimit: 4,
            layout: "grid",
            matchTags: "[]",
            styling: "{}",
          },
        ],
      },
    },
  });

  return quiz.id;
}

