 3→/**
 4→ * Converts a string to a URL-safe slug.
 5→ * e.g. "My Quiz Title!" -> "my-quiz-title"
 6→ */
 7→export function slugify(text: string): string {
 8→  return text
 9→    .toLowerCase()
10→    .replace(/[^a-z0-9\s-]/g, "")
11→    .replace(/\s+/g, "-")
12→    .replace(/-+/g, "-")
13→    .replace(/^-|-$/g, "");
