66→/**
67→ * Truncates a string to `maxLength` characters, appending "…" if truncated.
68→ */
69→export function truncate(text: string, maxLength: number): string {
70→  if (text.length <= maxLength) return text;
71→  return `${text.slice(0, maxLength - 1)}…`;
