import { showToast } from "../utils/toast";
import { useState, useCallback, useEffect } from "react";
import { data } from "react-router";
import type {
  ActionFunctionArgs,
  HeadersFunction,
  LoaderFunctionArgs,
} from "react-router";
import {
  useLoaderData,
  useNavigate,
  useSubmit,
  useFetcher,
} from "react-router";
import {
  Page,
  Layout,
  Card,
  Text,
  InlineStack,
  BlockStack,
  Badge,
  Button,
  Box,
  Divider,
  IndexTable,
  Modal,
  EmptyState,
  useIndexResourceState,
  ButtonGroup,
  SkeletonPage,
  SkeletonBodyText,
} from "@shopify/polaris";
import { authenticate } from "../shopify.server";
import { boundary } from "@shopify/shopify-app-react-router/server";
import { getQuizzes, deleteQuiz } from "../services/quiz.server";
import {
  getTemplatesMeta,
  createQuizFromTemplate,
  createBlankQuiz,
} from "../services/template.server";
import type { TemplateMeta } from "../services/template.server";
import db from "../db.server";
import { PLAN_LIMITS } from "../utils/constants";
import type { PlanId } from "../utils/constants";

// ─── Types ────────────────────────────────────────────────────────────────────

type BadgeTone = "success" | "attention" | "warning" | undefined;

type ActionSuccess = {
  success: true;
  quizId?: string;
  message: string;
};

type ActionError = {
  error: string;
};

type ActionResult = ActionSuccess | ActionError;

// ─── Status helpers ───────────────────────────────────────────────────────────

const statusToneMap: Record<string, BadgeTone> = {
  active: "success",
  draft: "attention",
  paused: "warning",
  archived: undefined,
};

function formatStatus(status: string): string {
  return status.charAt(0).toUpperCase() + status.slice(1);
}

function formatQuizType(type: string): string {
  return type
    .split("-")
    .map((word) => word.charAt(0).toUpperCase() + word.slice(1))
    .join(" ");
}

// ─── Template emoji mapping ───────────────────────────────────────────────────

const TEMPLATE_EMOJI: Record<string, string> = {
  skincare: "\uD83E\uDDF4",
  supplement: "\uD83D\uDC8A",
  style: "\uD83D\uDC57",
  haircare: "\uD83D\uDC87",
  fitness: "\uD83C\uDFCB\uFE0F",
  blank: "\u2795",
};

const BLANK_TEMPLATE: TemplateMeta = {
  id: "blank",
  name: "Start from blank",
  category: "Custom",
  questionCount: 0,
  questionTypes: "Build manually",
  badge: null,
};

const progressSteps = [
  "Reading product catalogue...",
  "Generating questions & answers...",
  "Mapping products to answers...",
  "Finalising your quiz...",
];

// ─── Plan limit helper (server-side only) ─────────────────────────────────────

async function checkPlanLimit(shop: string): Promise<string | null> {
  const count = await db.quiz.count({
    where: { shop, status: { not: "archived" } },
  });
  const sub = await db.subscription.findUnique({
    where: { shop },
    select: { planId: true },
  });
  const planId = (sub?.planId ?? "free") as PlanId;
  const limit = PLAN_LIMITS[planId]?.quizLimit ?? 1;
  if (count >= limit) {
    return `You've reached the ${limit}-quiz limit for your ${planId} plan. Upgrade to create more.`;
  }
  return null;
}

// ─── Loader ───────────────────────────────────────────────────────────────────

export const loader = async ({ request }: LoaderFunctionArgs) => {
  const { session } = await authenticate.admin(request);
  try {
    const [quizzes, templates] = await Promise.all([
      getQuizzes(session.shop),
      Promise.resolve(getTemplatesMeta()),
    ]);
    return { quizzes, templates };
  } catch {
    return { quizzes: [], templates: getTemplatesMeta() };
  }
};

// ─── Action ───────────────────────────────────────────────────────────────────

export const action = async ({
  request,
}: ActionFunctionArgs): Promise<ActionResult> => {
  const { session } = await authenticate.admin(request);
  const formData = await request.formData();
  const intent = formData.get("intent") as string;

  try {
    // ── Create from template ─────────────────────────────────────────────────
    if (intent === "create-from-template") {
      const templateId = formData.get("templateId") as string;
      if (!templateId) {
        return data<ActionResult>(
          { error: "Template ID is required" },
          { status: 400 },
        );
      }
      const limitError = await checkPlanLimit(session.shop);
      if (limitError) {
        return data<ActionResult>({ error: limitError }, { status: 403 });
      }
      const quizId = await createQuizFromTemplate(session.shop, templateId);
      return { success: true, quizId, message: "Quiz created from template!" };
    }

    // ── Create blank ─────────────────────────────────────────────────────────
    if (intent === "create-blank") {
      const limitError = await checkPlanLimit(session.shop);
      if (limitError) {
        return data<ActionResult>({ error: limitError }, { status: 403 });
      }
      const quizId = await createBlankQuiz(session.shop);
      return { success: true, quizId, message: "Quiz created!" };
    }

    // ── Archive ───────────────────────────────────────────────────────────────
    if (intent === "archive") {
      const id = formData.get("id") as string;
      const quiz = await db.quiz.findFirst({
        where: { id, shop: session.shop },
      });
      if (!quiz) {
        return data<ActionResult>(
          { error: "Quiz not found or access denied" },
          { status: 404 },
        );
      }
      await db.quiz.update({
        where: { id },
        data: { status: "archived" },
      });
      return { success: true, message: "Quiz archived" };
    }

    // ── Delete ────────────────────────────────────────────────────────────────
    if (intent === "delete") {
      const id = formData.get("id") as string;
      await deleteQuiz(id, session.shop);
      return { success: true, message: "Quiz deleted" };
    }

    return data<ActionResult>({ error: "Unknown intent" }, { status: 400 });
  } catch (error) {
    const message =
      error instanceof Error ? error.message : "Action failed";
    return data<ActionResult>({ error: message }, { status: 500 });
  }
};

// ─── Hydrate fallback (skeleton) ──────────────────────────────────────────────

export function HydrateFallback() {
  return (
    <SkeletonPage title="My Quizzes" primaryAction>
      <BlockStack gap="600">
        <Card>
          <SkeletonBodyText lines={8} />
        </Card>
      </BlockStack>
    </SkeletonPage>
  );
}

// ─── TemplateCard ─────────────────────────────────────────────────────────────

function TemplateCard({
  template,
  onSelect,
}: {
  template: TemplateMeta;
  onSelect: (id: string) => void;
}) {
  const badgeTone =
    template.badge === "Popular"
      ? ("success" as const)
      : template.badge === "New"
        ? ("info" as const)
        : undefined;

  const emoji = TEMPLATE_EMOJI[template.id] ?? "\uD83D\uDCCB";

  return (
    <div
      style={{
        cursor: "pointer",
        border: "1px solid var(--p-color-border)",
        borderRadius: "var(--p-border-radius-300)",
        padding: "16px",
        transition: "box-shadow 0.15s ease",
        height: "100%",
      }}
      onClick={() => onSelect(template.id)}
      onMouseEnter={(e) => {
        (e.currentTarget as HTMLElement).style.boxShadow =
          "0 0 0 2px var(--p-color-border-emphasis)";
      }}
      onMouseLeave={(e) => {
        (e.currentTarget as HTMLElement).style.boxShadow = "none";
      }}
      role="button"
      tabIndex={0}
      onKeyDown={(e) => {
        if (e.key === "Enter" || e.key === " ") {
          e.preventDefault();
          onSelect(template.id);
        }
      }}
      aria-label={`Select template: ${template.name}`}
    >
      <BlockStack gap="300">
        <InlineStack align="space-between" blockAlign="start">
          <Text as="span" variant="headingXl">
            {emoji}
          </Text>
          {template.badge && (
            <Badge tone={badgeTone}>{template.badge}</Badge>
          )}
        </InlineStack>
        <BlockStack gap="100">
          <Text as="p" variant="headingSm" fontWeight="semibold">
            {template.name}
          </Text>
          <InlineStack gap="100" wrap>
            {template.category.split(", ").map((cat) => (
              <Badge key={cat} tone="info">
                {cat}
              </Badge>
            ))}
          </InlineStack>
        </BlockStack>
        <Text as="p" variant="bodySm" tone="subdued">
          {template.questionCount === 0
            ? "No pre-built questions"
            : `${template.questionCount} questions`}
        </Text>
      </BlockStack>
    </div>
  );
}

// ─── AIGenerationOverlay ──────────────────────────────────────────────────────

function AIGenerationOverlay({ onAnimationDone }: { onAnimationDone: () => void }) {
  const [currentStep, setCurrentStep] = useState(0);
  const [completedSteps, setCompletedSteps] = useState<number[]>([]);

  useEffect(() => {
    const timers: ReturnType<typeof setTimeout>[] = [];

    progressSteps.forEach((_, index) => {
      const advanceTimer = setTimeout(() => {
        setCurrentStep(index);
        if (index > 0) {
          setCompletedSteps((prev) =>
            prev.includes(index - 1) ? prev : [...prev, index - 1],
          );
        }
      }, index * 750);
      timers.push(advanceTimer);
    });

    // Mark the last step complete
    const lastCompleteTimer = setTimeout(() => {
      setCompletedSteps((prev) =>
        prev.includes(progressSteps.length - 1)
          ? prev
          : [...prev, progressSteps.length - 1],
      );
    }, progressSteps.length * 750);
    timers.push(lastCompleteTimer);

    // Signal animation is done with a small buffer
    const doneTimer = setTimeout(() => {
      onAnimationDone();
    }, progressSteps.length * 750 + 500);
    timers.push(doneTimer);

    return () => timers.forEach(clearTimeout);
    // onAnimationDone is stable (wrapped in useCallback at the call site)
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  return (
    <div
      style={{
        position: "fixed",
        inset: 0,
        zIndex: 9999,
        background: "rgba(255, 255, 255, 0.97)",
        display: "flex",
        alignItems: "center",
        justifyContent: "center",
      }}
    >
      <div style={{ textAlign: "center", maxWidth: 420 }}>
        {/* Spinner */}
        <div
          style={{
            width: 64,
            height: 64,
            margin: "0 auto 24px",
            border: "4px solid var(--p-color-border)",
            borderTopColor: "var(--p-color-border-emphasis)",
            borderRadius: "50%",
            animation: "quizsnap-spin 0.8s linear infinite",
          }}
        />
        <style>{`@keyframes quizsnap-spin { to { transform: rotate(360deg); } }`}</style>

        <BlockStack gap="200">
          <Text as="p" variant="headingLg" fontWeight="bold">
            Building your quiz with AI...
          </Text>
          <Text as="p" variant="bodySm" tone="subdued">
            This usually takes a few seconds
          </Text>
        </BlockStack>

        <div style={{ marginTop: 32, textAlign: "left" }}>
          <BlockStack gap="300">
            {progressSteps.map((step, index) => {
              const isCompleted = completedSteps.includes(index);
              const isCurrent = currentStep === index && !isCompleted;
              return (
                <InlineStack key={index} gap="300" blockAlign="center">
                  <div
                    style={{
                      width: 24,
                      height: 24,
                      borderRadius: "50%",
                      display: "flex",
                      alignItems: "center",
                      justifyContent: "center",
                      fontSize: 14,
                      flexShrink: 0,
                      background: isCompleted
                        ? "var(--p-color-bg-fill-success)"
                        : isCurrent
                          ? "var(--p-color-bg-fill-emphasis)"
                          : "var(--p-color-bg-surface-secondary)",
                      color:
                        isCompleted || isCurrent
                          ? "#fff"
                          : "var(--p-color-text-subdued)",
                    }}
                  >
                    {isCompleted ? "\u2713" : index + 1}
                  </div>
                  <Text
                    as="p"
                    variant="bodyMd"
                    tone={
                      isCompleted
                        ? "success"
                        : isCurrent
                          ? undefined
                          : "subdued"
                    }
                    fontWeight={isCurrent ? "semibold" : "regular"}
                  >
                    {step}
                  </Text>
                </InlineStack>
              );
            })}
          </BlockStack>
        </div>
      </div>
    </div>
  );
}

// ─── Main page ────────────────────────────────────────────────────────────────

export default function MyQuizzes() {
  const { quizzes, templates } = useLoaderData<typeof loader>();
  const navigate = useNavigate();
  const submit = useSubmit();

  // Fetcher is used exclusively for quiz creation so the page doesn't navigate
  // away during submission (the action returns a quizId we then navigate to).
  const fetcher = useFetcher<ActionResult>();

  const [modalOpen, setModalOpen] = useState(false);
  const [showAIOverlay, setShowAIOverlay] = useState(false);
  const [animationDone, setAnimationDone] = useState(false);

  const isCreating = fetcher.state !== "idle";
  const showEmptyState = quizzes.length === 0;

  // ── Navigate after creation ────────────────────────────────────────────────
  useEffect(() => {
    if (!fetcher.data) return;

    if ("error" in fetcher.data) {
      showToast(String(fetcher.data.error), { isError: true });
      setShowAIOverlay(false);
      setAnimationDone(false);
      return;
    }

    if ("quizId" in fetcher.data && fetcher.data.quizId) {
      const { quizId, message } = fetcher.data;

      if (!showAIOverlay) {
        // Blank quiz — navigate immediately
        showToast(message ?? "Quiz created!");
        navigate(`/app/quizzes/${quizId}`);
      } else if (animationDone) {
        // Template quiz — both animation and creation are complete
        showToast("AI built your quiz from your catalogue!");
        setShowAIOverlay(false);
        navigate(`/app/quizzes/${quizId}`);
      }
      // If quizId is ready but animation isn't done yet, the animationDone
      // branch of this effect will fire once animationDone flips to true.
    }
  }, [fetcher.data, animationDone, showAIOverlay, navigate]);

  // ── Template selection ─────────────────────────────────────────────────────
  const handleSelectTemplate = useCallback(
    (templateId: string) => {
      setModalOpen(false);

      if (templateId === "blank") {
        fetcher.submit(
          { intent: "create-blank" },
          { method: "POST" },
        );
      } else {
        setShowAIOverlay(true);
        setAnimationDone(false);
        fetcher.submit(
          { intent: "create-from-template", templateId },
          { method: "POST" },
        );
      }
    },
    [fetcher],
  );

  const handleAnimationDone = useCallback(() => {
    setAnimationDone(true);
  }, []);

  // ── Row action handlers (use regular submit — archive/delete stay on page) ──
  const handleEditQuiz = useCallback(
    (id: string) => navigate(`/app/quizzes/${id}`),
    [navigate],
  );

  const handlePreviewQuiz = useCallback(
    (id: string) => navigate(`/app/quizzes/${id}/preview`),
    [navigate],
  );

  const handleArchiveQuiz = useCallback(
    (id: string) => {
      const formData = new FormData();
      formData.append("intent", "archive");
      formData.append("id", id);
      submit(formData, { method: "POST" });
      showToast("Quiz archived");
    },
    [submit],
  );

  // ── IndexTable selection state ─────────────────────────────────────────────
  const resourceName = { singular: "quiz", plural: "quizzes" };
  const { selectedResources, allResourcesSelected, handleSelectionChange } =
    useIndexResourceState(quizzes);

  // ── Row markup ─────────────────────────────────────────────────────────────
  const rowMarkup = quizzes.map(
    (
      quiz: {
        id: string;
        title: string;
        type: string;
        status: string;
        completions: number;
        updatedAt: Date | string;
        _count: { questions: number; responses: number };
      },
      index: number,
    ) => (
      <IndexTable.Row
        id={quiz.id}
        key={quiz.id}
        selected={selectedResources.includes(quiz.id)}
        position={index}
      >
        <IndexTable.Cell>
          <InlineStack gap="300" blockAlign="center">
            <Text as="span" variant="headingMd">
              {"📊"}
            </Text>
            <BlockStack gap="050">
              <Text as="span" variant="bodyMd" fontWeight="semibold">
                {quiz.title}
              </Text>
              <Text as="span" variant="bodySm" tone="subdued">
                {formatQuizType(quiz.type)}
              </Text>
            </BlockStack>
          </InlineStack>
        </IndexTable.Cell>
        <IndexTable.Cell>
          <Badge tone={statusToneMap[quiz.status]}>
            {formatStatus(quiz.status)}
          </Badge>
        </IndexTable.Cell>
        <IndexTable.Cell>
          <Text as="span" variant="bodyMd" alignment="end">
            {quiz._count.questions}
          </Text>
        </IndexTable.Cell>
        <IndexTable.Cell>
          <Text as="span" variant="bodyMd" alignment="end">
            {quiz.completions.toLocaleString()}
          </Text>
        </IndexTable.Cell>
        <IndexTable.Cell>
          <Text as="span" variant="bodyMd" alignment="end">
            {"—"}
          </Text>
        </IndexTable.Cell>
        <IndexTable.Cell>
          <Text as="span" variant="bodyMd" alignment="end">
            {"—"}
          </Text>
        </IndexTable.Cell>
        <IndexTable.Cell>
          <Text as="span" variant="bodySm" tone="subdued">
            {new Date(quiz.updatedAt).toLocaleDateString("en-US", {
              month: "short",
              day: "numeric",
              year: "numeric",
            })}
          </Text>
        </IndexTable.Cell>
        <IndexTable.Cell>
          <ButtonGroup>
            <Button size="slim" onClick={() => handleEditQuiz(quiz.id)}>
              Edit
            </Button>
            <Button
              size="slim"
              variant="plain"
              onClick={() => handlePreviewQuiz(quiz.id)}
            >
              Preview
            </Button>
            <Button
              size="slim"
              variant="plain"
              tone="critical"
              onClick={() => handleArchiveQuiz(quiz.id)}
            >
              Archive
            </Button>
          </ButtonGroup>
        </IndexTable.Cell>
      </IndexTable.Row>
    ),
  );

  // ── All templates including the blank option ───────────────────────────────
  const allTemplates: TemplateMeta[] = [...templates, BLANK_TEMPLATE];

  // ── Render ─────────────────────────────────────────────────────────────────
  return (
    <>
      {showAIOverlay && (
        <AIGenerationOverlay onAnimationDone={handleAnimationDone} />
      )}

      <Page
        title="My Quizzes"
        primaryAction={{
          content: "+ Create quiz",
          onAction: () => setModalOpen(true),
          loading: isCreating && !showAIOverlay,
        }}
      >
        <BlockStack gap="600">
          {showEmptyState ? (
            <Card>
              <EmptyState
                heading="Create your first quiz"
                action={{
                  content: "Create quiz",
                  onAction: () => setModalOpen(true),
                }}
                image="https://cdn.shopify.com/s/files/1/0262/4071/2726/files/emptystate-files.png"
              >
                <p>
                  Build product recommendation quizzes that help your customers
                  find the perfect product and boost your sales.
                </p>
              </EmptyState>
            </Card>
          ) : (
            <Layout>
              <Layout.Section>
                <Card padding="0">
                  <BlockStack>
                    <Box padding="400">
                      <InlineStack align="space-between" blockAlign="center">
                        <Text as="h2" variant="headingMd">
                          All Quizzes
                        </Text>
                        <Text as="p" variant="bodySm" tone="subdued">
                          {quizzes.length}{" "}
                          {quizzes.length === 1 ? "quiz" : "quizzes"}
                        </Text>
                      </InlineStack>
                    </Box>
                    <IndexTable
                      resourceName={resourceName}
                      itemCount={quizzes.length}
                      selectedItemsCount={
                        allResourcesSelected ? "All" : selectedResources.length
                      }
                      onSelectionChange={handleSelectionChange}
                      headings={[
                        { title: "Quiz" },
                        { title: "Status" },
                        { title: "Questions", alignment: "end" },
                        { title: "Completions", alignment: "end" },
                        { title: "Conv. Rate", alignment: "end" },
                        { title: "Revenue", alignment: "end" },
                        { title: "Updated" },
                        { title: "Actions" },
                      ]}
                    >
                      {rowMarkup}
                    </IndexTable>
                  </BlockStack>
                </Card>
              </Layout.Section>
            </Layout>
          )}
        </BlockStack>
      </Page>

      {/* Template picker modal */}
      <Modal
        open={modalOpen}
        onClose={() => setModalOpen(false)}
        title="Choose a template"
        size="large"
      >
        <Box padding="400">
          <BlockStack gap="400">
            <BlockStack gap="100">
              <Text as="h2" variant="headingLg" fontWeight="bold">
                Choose a template
              </Text>
              <Text as="p" variant="bodyMd" tone="subdued">
                Pick a pre-built quiz template or start from scratch
              </Text>
            </BlockStack>
            <Divider />
            <div
              style={{
                display: "grid",
                gridTemplateColumns: "repeat(3, 1fr)",
                gap: "16px",
              }}
            >
              {allTemplates.map((template) => (
                <TemplateCard
                  key={template.id}
                  template={template}
                  onSelect={handleSelectTemplate}
                />
              ))}
            </div>
          </BlockStack>
        </Box>
      </Modal>
    </>
  );
}

export const headers: HeadersFunction = (headersArgs) => {
  return boundary.headers(headersArgs);
};

