 46→
 47→// ─── Types ────────────────────────────────────────────────────────────────────
 48→
 49→type BadgeTone = "success" | "attention" | "warning" | undefined;
 50→
 51→type ActionSuccess = {
 52→  success: true;
 53→  quizId?: string;
 54→  message: string;
