 66→  active: "success",
 67→  draft: "attention",
 68→  paused: "warning",
 69→  archived: undefined,
 70→};
 71→
 72→function formatStatus(status: string): string {
 73→  return status.charAt(0).toUpperCase() + status.slice(1);
 74→}
 75→
 76→function formatQuizType(type: string): string {
 77→  return type
 78→    .split("-")
 79→    .map((word) => word.charAt(0).toUpperCase() + word.slice(1))
 80→    .join(" ");
 81→}
 82→
 83→// ─── Template emoji mapping ───────────────────────────────────────────────────
 84→
 85→const TEMPLATE_EMOJI: Record<string, string> = {
 86→  skincare: "\uD83E\uDDF4",
 87→  supplement: "\uD83D\uDC8A",
 88→  style: "\uD83D\uDC57",
 89→  haircare: "\uD83D\uDC87",
 90→  fitness: "\uD83C\uDFCB\uFE0F",
 91→  blank: "\u2795",
 92→};
 93→
 94→const BLANK_TEMPLATE: TemplateMeta = {
 95→  id: "blank",
 96→  name: "Start from blank",
 97→  category: "Custom",
 98→  questionCount: 0,
 99→  questionTypes: "Build manually",
100→  badge: null,
101→};
102→
103→const progressSteps = [
104→  "Reading product catalogue...",
105→  "Generating questions & answers...",
106→  "Mapping products to answers...",
