110→// ─── Plan limit helper (server-side only) ─────────────────────────────────────
111→
112→async function checkPlanLimit(shop: string): Promise<string | null> {
113→  const count = await db.quiz.count({
114→    where: { shop, status: { not: "archived" } },
115→  });
116→  const sub = await db.subscription.findUnique({
117→    where: { shop },
118→    select: { planId: true },
119→  });
120→  const planId = (sub?.planId ?? "free") as PlanId;
121→  const limit = PLAN_LIMITS[planId]?.quizLimit ?? 1;
122→  if (count >= limit) {
123→    return `You've reached the ${limit}-quiz limit for your ${planId} plan. Upgrade to create more.`;
124→  }
125→  return null;
126→}
127→
128→// ─── Loader ───────────────────────────────────────────────────────────────────
129→
130→export const loader = async ({ request }: LoaderFunctionArgs) => {
131→  const { session } = await authenticate.admin(request);
132→  try {
133→    const [quizzes, templates] = await Promise.all([
134→      getQuizzes(session.shop),
135→      Promise.resolve(getTemplatesMeta()),
136→    ]);
137→    return { quizzes, templates };
138→  } catch {
139→    return { quizzes: [], templates: getTemplatesMeta() };
140→  }
141→};
142→
143→// ─── Action ───────────────────────────────────────────────────────────────────
144→
145→export const action = async ({
146→  request,
147→}: ActionFunctionArgs): Promise<ActionResult> => {
148→  const { session } = await authenticate.admin(request);
149→  const formData = await request.formData();
150→  const intent = formData.get("intent") as string;
151→
152→  try {
153→    // ── Create from template ─────────────────────────────────────────────────
154→    if (intent === "create-from-template") {
155→      const templateId = formData.get("templateId") as string;
156→      if (!templateId) {
157→        return data<ActionResult>(
158→          { error: "Template ID is required" },
159→          { status: 400 },
160→        );
161→      }
162→      const limitError = await checkPlanLimit(session.shop);
163→      if (limitError) {
164→        return data<ActionResult>({ error: limitError }, { status: 403 });
165→      }
166→      const quizId = await createQuizFromTemplate(session.shop, templateId);
167→      return { success: true, quizId, message: "Quiz created from template!" };
168→    }
169→
170→    // ── Create blank ─────────────────────────────────────────────────────────
171→    if (intent === "create-blank") {
172→      const limitError = await checkPlanLimit(session.shop);
173→      if (limitError) {
174→        return data<ActionResult>({ error: limitError }, { status: 403 });
175→      }
176→      const quizId = await createBlankQuiz(session.shop);
177→      return { success: true, quizId, message: "Quiz created!" };
178→    }
179→
180→    // ── Archive ───────────────────────────────────────────────────────────────
181→    if (intent === "archive") {
182→      const id = formData.get("id") as string;
183→      const quiz = await db.quiz.findFirst({
184→        where: { id, shop: session.shop },
185→      });
186→      if (!quiz) {
187→        return data<ActionResult>(
188→          { error: "Quiz not found or access denied" },
189→          { status: 404 },
190→        );
191→      }
192→      await db.quiz.update({
193→        where: { id },
194→        data: { status: "archived" },
195→      });
196→      return { success: true, message: "Quiz archived" };
197→    }
198→
199→    // ── Delete ────────────────────────────────────────────────────────────────
200→    if (intent === "delete") {
201→      const id = formData.get("id") as string;
202→      await deleteQuiz(id, session.shop);
203→      return { success: true, message: "Quiz deleted" };
204→    }
205→
206→    return data<ActionResult>({ error: "Unknown intent" }, { status: 400 });
207→  } catch (error) {
208→    const message =
209→      error instanceof Error ? error.message : "Action failed";
210→    return data<ActionResult>({ error: message }, { status: 500 });
211→  }
212→};
