305→// ─── AIGenerationOverlay ──────────────────────────────────────────────────────
306→
307→function AIGenerationOverlay({ onAnimationDone }: { onAnimationDone: () => void }) {
308→  const [currentStep, setCurrentStep] = useState(0);
309→  const [completedSteps, setCompletedSteps] = useState<number[]>([]);
310→
311→  useEffect(() => {
312→    const timers: ReturnType<typeof setTimeout>[] = [];
313→
314→    progressSteps.forEach((_, index) => {
315→      const advanceTimer = setTimeout(() => {
316→        setCurrentStep(index);
317→        if (index > 0) {
318→          setCompletedSteps((prev) =>
319→            prev.includes(index - 1) ? prev : [...prev, index - 1],
320→          );
321→        }
322→      }, index * 750);
323→      timers.push(advanceTimer);
324→    });
325→
326→    // Mark the last step complete
327→    const lastCompleteTimer = setTimeout(() => {
328→      setCompletedSteps((prev) =>
329→        prev.includes(progressSteps.length - 1)
330→          ? prev
331→          : [...prev, progressSteps.length - 1],
332→      );
333→    }, progressSteps.length * 750);
334→    timers.push(lastCompleteTimer);
335→
336→    // Signal animation is done with a small buffer
337→    const doneTimer = setTimeout(() => {
338→      onAnimationDone();
339→    }, progressSteps.length * 750 + 500);
340→    timers.push(doneTimer);
341→
342→    return () => timers.forEach(clearTimeout);
343→    // onAnimationDone is stable (wrapped in useCallback at the call site)
344→    // eslint-disable-next-line react-hooks/exhaustive-deps
345→  }, []);
346→
347→  return (
348→    <div
349→      style={{
350→        position: "fixed",
351→        inset: 0,
352→        zIndex: 9999,
353→        background: "rgba(255, 255, 255, 0.97)",
354→        display: "flex",
355→        alignItems: "center",
356→        justifyContent: "center",
357→      }}
358→    >
359→      <div style={{ textAlign: "center", maxWidth: 420 }}>
360→        {/* Spinner */}
361→        <div
362→          style={{
363→            width: 64,
364→            height: 64,
365→            margin: "0 auto 24px",
366→            border: "4px solid var(--p-color-border)",
367→            borderTopColor: "var(--p-color-border-emphasis)",
368→            borderRadius: "50%",
369→            animation: "quizsnap-spin 0.8s linear infinite",
370→          }}
371→        />
372→        <style>{`@keyframes quizsnap-spin { to { transform: rotate(360deg); } }`}</style>
373→
374→        <BlockStack gap="200">
375→          <Text as="p" variant="headingLg" fontWeight="bold">
376→            Building your quiz with AI...
377→          </Text>
378→          <Text as="p" variant="bodySm" tone="subdued">
379→            This usually takes a few seconds
380→          </Text>
381→        </BlockStack>
382→
383→        <div style={{ marginTop: 32, textAlign: "left" }}>
384→          <BlockStack gap="300">
385→            {progressSteps.map((step, index) => {
386→              const isCompleted = completedSteps.includes(index);
387→              const isCurrent = currentStep === index && !isCompleted;
388→              return (
389→                <InlineStack key={index} gap="300" blockAlign="center">
390→                  <div
391→                    style={{
392→                      width: 24,
393→                      height: 24,
394→                      borderRadius: "50%",
395→                      display: "flex",
396→                      alignItems: "center",
397→                      justifyContent: "center",
398→                      fontSize: 14,
399→                      flexShrink: 0,
400→                      background: isCompleted
401→                        ? "var(--p-color-bg-fill-success)"
402→                        : isCurrent
403→                          ? "var(--p-color-bg-fill-emphasis)"
404→                          : "var(--p-color-bg-surface-secondary)",
405→                      color:
406→                        isCompleted || isCurrent
407→                          ? "#fff"
408→                          : "var(--p-color-text-subdued)",
409→                    }}
410→                  >
411→                    {isCompleted ? "\u2713" : index + 1}
412→                  </div>
413→                  <Text
414→                    as="p"
415→                    variant="bodyMd"
416→                    tone={
417→                      isCompleted
418→                        ? "success"
419→                        : isCurrent
420→                          ? undefined
421→                          : "subdued"
422→                    }
423→                    fontWeight={isCurrent ? "semibold" : "regular"}
424→                  >
425→                    {step}
426→                  </Text>
427→                </InlineStack>
428→              );
429→            })}
430→          </BlockStack>
431→        </div>
432→      </div>
433→    </div>
434→  );
435→}
