437→// ─── Main page ────────────────────────────────────────────────────────────────
438→
439→export default function MyQuizzes() {
440→  const { quizzes, templates } = useLoaderData<typeof loader>();
441→  const navigate = useNavigate();
442→  const submit = useSubmit();
443→
444→  // Fetcher is used exclusively for quiz creation so the page doesn't navigate
445→  // away during submission (the action returns a quizId we then navigate to).
446→  const fetcher = useFetcher<ActionResult>();
447→
448→  const [modalOpen, setModalOpen] = useState(false);
449→  const [showAIOverlay, setShowAIOverlay] = useState(false);
450→  const [animationDone, setAnimationDone] = useState(false);
451→
452→  const isCreating = fetcher.state !== "idle";
453→  const showEmptyState = quizzes.length === 0;
454→
455→  // ── Navigate after creation ────────────────────────────────────────────────
456→  useEffect(() => {
457→    if (!fetcher.data) return;
458→
459→    if ("error" in fetcher.data) {
460→      showToast(String(fetcher.data.error), { isError: true });
461→      setShowAIOverlay(false);
462→      setAnimationDone(false);
463→      return;
464→    }
465→
466→    if ("quizId" in fetcher.data && fetcher.data.quizId) {
467→      const { quizId, message } = fetcher.data;
468→
469→      if (!showAIOverlay) {
470→        // Blank quiz — navigate immediately
471→        showToast(message ?? "Quiz created!");
472→        navigate(`/app/quizzes/${quizId}`);
473→      } else if (animationDone) {
474→        // Template quiz — both animation and creation are complete
475→        showToast("AI built your quiz from your catalogue!");
476→        setShowAIOverlay(false);
477→        navigate(`/app/quizzes/${quizId}`);
478→      }
479→      // If quizId is ready but animation isn't done yet, the animationDone
480→      // branch of this effect will fire once animationDone flips to true.
481→    }
482→  }, [fetcher.data, animationDone, showAIOverlay, navigate]);
483→
484→  // ── Template selection ─────────────────────────────────────────────────────
485→  const handleSelectTemplate = useCallback(
486→    (templateId: string) => {
487→      setModalOpen(false);
488→
489→      if (templateId === "blank") {
490→        fetcher.submit(
491→          { intent: "create-blank" },
492→          { method: "POST" },
493→        );
494→      } else {
495→        setShowAIOverlay(true);
496→        setAnimationDone(false);
497→        fetcher.submit(
498→          { intent: "create-from-template", templateId },
499→          { method: "POST" },
500→        );
501→      }
502→    },
503→    [fetcher],
504→  );
505→
506→  const handleAnimationDone = useCallback(() => {
507→    setAnimationDone(true);
508→  }, []);
509→
510→  // ── Row action handlers (use regular submit — archive/delete stay on page) ──
511→  const handleEditQuiz = useCallback(
512→    (id: string) => navigate(`/app/quizzes/${id}`),
513→    [navigate],
514→  );
515→
516→  const handlePreviewQuiz = useCallback(
517→    (id: string) => navigate(`/app/quizzes/${id}/preview`),
518→    [navigate],
519→  );
520→
521→  const handleArchiveQuiz = useCallback(
522→    (id: string) => {
523→      const formData = new FormData();
524→      formData.append("intent", "archive");
525→      formData.append("id", id);
526→      submit(formData, { method: "POST" });
527→      showToast("Quiz archived");
528→    },
529→    [submit],
530→  );
531→
532→  // ── IndexTable selection state ─────────────────────────────────────────────
533→  const resourceName = { singular: "quiz", plural: "quizzes" };
534→  const { selectedResources, allResourcesSelected, handleSelectionChange } =
535→    useIndexResourceState(quizzes);
536→
537→  // ── Row markup ─────────────────────────────────────────────────────────────
538→  const rowMarkup = quizzes.map(
539→    (
540→      quiz: {
541→        id: string;
542→        title: string;
543→        type: string;
544→        status: string;
545→        completions: number;
546→        updatedAt: Date | string;
547→        _count: { questions: number; responses: number };
548→      },
549→      index: number,
550→    ) => (
551→      <IndexTable.Row
552→        id={quiz.id}
553→        key={quiz.id}
554→        selected={selectedResources.includes(quiz.id)}
555→        position={index}
556→      >
557→        <IndexTable.Cell>
558→          <InlineStack gap="300" blockAlign="center">
559→            <Text as="span" variant="headingMd">
560→              {"📊"}
561→            </Text>
562→            <BlockStack gap="050">
563→              <Text as="span" variant="bodyMd" fontWeight="semibold">
564→                {quiz.title}
565→              </Text>
566→              <Text as="span" variant="bodySm" tone="subdued">
567→                {formatQuizType(quiz.type)}
568→              </Text>
569→            </BlockStack>
570→          </InlineStack>
571→        </IndexTable.Cell>
572→        <IndexTable.Cell>
573→          <Badge tone={statusToneMap[quiz.status]}>
574→            {formatStatus(quiz.status)}
575→          </Badge>
576→        </IndexTable.Cell>
577→        <IndexTable.Cell>
578→          <Text as="span" variant="bodyMd" alignment="end">
579→            {quiz._count.questions}
580→          </Text>
581→        </IndexTable.Cell>
582→        <IndexTable.Cell>
583→          <Text as="span" variant="bodyMd" alignment="end">
584→            {quiz.completions.toLocaleString()}
585→          </Text>
586→        </IndexTable.Cell>
587→        <IndexTable.Cell>
588→          <Text as="span" variant="bodyMd" alignment="end">
589→            {"—"}
590→          </Text>
591→        </IndexTable.Cell>
592→        <IndexTable.Cell>
593→          <Text as="span" variant="bodyMd" alignment="end">
594→            {"—"}
595→          </Text>
596→        </IndexTable.Cell>
597→        <IndexTable.Cell>
